files.content:
:root {
  --bg: #2b2d42;
  --card: #edf2f4;
  --primary: #ef233c;
  --secondary: #8d99ae;
  --accent: #f9c74f;
  --text: #2b2d42;
  --bar-bg: #d3d9e0;
  --hunger: #e76f51;
  --happiness: #f4a261;
  --energy: #2a9d8f;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.card {
  background: var(--card);
  border-radius: 24px;
  padding: 32px 24px;
  max-width: 400px;
  width: 100%;
  text-align: center;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.3);
}

h1 {
  font-size: 1.75rem;
  margin-bottom: 24px;
  color: var(--primary);
  letter-spacing: 1px;
}

.pet {
  display: flex;
  justify-content: center;
  margin-bottom: 16px;
}

.pet-body {
  width: 120px;
  height: 120px;
  background: var(--accent);
  border-radius: 16px;
  position: relative;
  box-shadow: inset -8px -8px 0 rgba(0, 0, 0, 0.15);
  image-rendering: pixelated;
}

.pet-eye {
  width: 20px;
  height: 20px;
  background: var(--text);
  position: absolute;
  top: 30px;
  border-radius: 4px;
}

.pet-eye.left { left: 24px; }
.pet-eye.right { right: 24px; }

.pet-mouth {
  width: 40px;
  height: 12px;
  background: var(--text);
  position: absolute;
  bottom: 30px;
  left: 50%;
  transform: translateX(-50%);
  border-radius: 0 0 8px 8px;
  transition: all 0.2s;
}

.pet-mouth.sad {
  border-radius: 8px 8px 0 0;
  height: 8px;
}

.mood {
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 24px;
  color: var(--secondary);
  min-height: 1.5em;
}

.bars {
  display: flex;
  flex-direction: column;
  gap: 12px;
  margin-bottom: 24px;
}

.bar-group {
  text-align: left;
}

.bar-group label {
  display: block;
  font-size: 0.875rem;
  font-weight: 600;
  margin-bottom: 4px;
  color: var(--secondary);
}

.bar {
  height: 16px;
  background: var(--bar-bg);
  border-radius: 8px;
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  border-radius: 8px;
  transition: width 0.3s ease;
}

.bar-fill.hunger { background: var(--hunger); }
.bar-fill.happiness { background: var(--happiness); }
.bar-fill.energy { background: var(--energy); }

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

button {
  font-family: inherit;
  font-size: 1rem;
  font-weight: 600;
  padding: 12px 20px;
  border: none;
  border-radius: 12px;
  background: var(--secondary);
  color: #fff;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  min-width: 80px;
}

button:hover {
  background: var(--primary);
}

button:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

button:active {
  transform: scale(0.96);
  background: var(--primary);
}

@media (max-width: 360px) {
  .card { padding: 24px 16px; }
  .controls { flex-direction: column; }
  button { width: 100%; }
}

const state = {
  hunger: 70,
  happiness: 70,
  energy: 70
};

const moodEl = document.getElementById('mood');
const petMouth = document.getElementById('petMouth');
const bars = {
  hunger: document.getElementById('hungerBar'),
  happiness: document.getElementById('happinessBar'),
  energy: document.getElementById('energyBar')
};

function clamp(value) {
  return Math.max(0, Math.min(100, value));
}

function updateUI() {
  for (const key in bars) {
    const bar = bars[key];
    const fill = bar.querySelector('.bar-fill');
    const value = state[key];
    fill.style.width = value + '%';
    bar.setAttribute('aria-valuenow', value);
    bar.textContent = value;
  }

  let mood = 'Happy';
  if (state.hunger < 30) mood = 'Hungry';
  else if (state.energy < 30) mood = 'Tired';
  else if (state.happiness < 30) mood = 'Sad';
  else if (state.hunger > 80 && state.happiness > 80 && state.energy > 80) mood = 'Ecstatic';

  moodEl.textContent = mood;
  petMouth.classList.toggle('sad', mood === 'Sad' || mood === 'Hungry' || mood === 'Tired');
}

function feed() {
  state.hunger = clamp(state.hunger + 20);
  state.energy = clamp(state.energy - 5);
  updateUI();
}

function play() {
  state.happiness = clamp(state.happiness + 20);
  state.energy = clamp(state.energy - 15);
  state.hunger = clamp(state.hunger - 10);
  updateUI();
}

function sleep() {
  state.energy = clamp(state.energy + 25);
  state.hunger = clamp(state.hunger - 10);
  state.happiness = clamp(state.happiness - 5);
  updateUI();
}

document.getElementById('feedBtn').addEventListener('click', feed);
document.getElementById('playBtn').addEventListener('click', play);
document.getElementById('sleepBtn').addEventListener('click', sleep);

updateUI();
